const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/app/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================================\n// MONETIZATION ENUMS\n// ============================================================================\n\nenum Role {\n  USER\n  MODERATOR\n  CONTENT_MANAGER\n  ADMIN\n  SUPERADMIN\n}\n\nenum ContentStatus {\n  DRAFT\n  PROCESSING\n  READY\n  PUBLISHED\n  ARCHIVED\n}\n\nenum ContentAccessType {\n  FREE\n  SUBSCRIPTION\n  PREMIUM\n  RENTAL\n  PURCHASE\n  ADMIN_ONLY\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  TRIALING\n  PENDING\n  PAST_DUE\n  PAUSED\n  CANCELED\n  CANCELLED\n  EXPIRED\n}\n\nenum BillingInterval {\n  DAILY\n  WEEKLY\n  MONTHLY\n  YEARLY\n  ONE_TIME\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  CANCELLED\n  REFUNDED\n  PARTIALLY_REFUNDED\n}\n\nenum PaymentMethod {\n  MPESA\n  CARD\n  PAYPAL\n  BANK_TRANSFER\n  WALLET\n}\n\nenum PaymentProvider {\n  MPESA_DARAJA\n  FLUTTERWAVE\n  PESAPAL\n  STRIPE\n  PAYPAL\n}\n\nenum AdType {\n  PRE_ROLL\n  MID_ROLL\n  POST_ROLL\n  HOME_BANNER\n  CONTENT_BANNER\n  SPONSORED_CONTENT\n}\n\nenum AdEventType {\n  IMPRESSION\n  CLICK\n  COMPLETION\n  SKIP\n}\n\nenum PayoutStatus {\n  PENDING\n  PROCESSING\n  PAID\n  FAILED\n  CANCELLED\n}\n\nenum CouponDiscountType {\n  PERCENTAGE\n  FIXED_AMOUNT\n}\n\nenum AssetType {\n  POSTER\n  BACKDROP\n  BANNER\n  STILL\n  LOGO\n  HERO_ART\n}\n\nenum VideoResolution {\n  P240\n  P360\n  P480\n  P720\n  P1080\n  UHD_4K\n  UHD_8K\n}\n\nenum VideoSourceType {\n  HLS\n  DASH\n  MP4\n}\n\nenum HDRFormat {\n  SDR\n  HDR10\n  DOLBY_VISION\n  HLG\n}\n\nenum RatingValue {\n  THUMBS_DOWN\n  THUMBS_UP\n  DOUBLE_THUMBS_UP\n}\n\nenum DeviceType {\n  WEB\n  MOBILE_IOS\n  MOBILE_ANDROID\n  SMART_TV\n  APPLE_TV\n  ROKU\n  FIRE_TV\n  PLAYSTATION\n  XBOX\n}\n\nenum RowRenderStyle {\n  STANDARD_POSTER\n  WIDE_BACKDROP\n  HERO_BILLBOARD\n  TOP_10_NUMERIC\n  CONTINUE_WATCHING\n}\n\nenum RowDataSource {\n  CURATED_COLLECTION\n  TRENDING\n  POPULAR\n  NEW_RELEASES\n  TOP_10\n  CONTINUE_WATCHING\n  RECOMMENDED\n  CATEGORY_ROW\n  SIMILAR_TO_HISTORY\n  BILLBOARD\n}\n\n// ============================================================================\n// USER & CORE SYSTEM\n// ============================================================================\n\nmodel MaturityRating {\n  id           String    @id @default(uuid())\n  code         String    @unique\n  system       String\n  severityRank Int\n  description  String?\n  createdAt    DateTime  @default(now())\n  contentItems Content[]\n  profiles     Profile[]\n}\n\nmodel LanguageRegistry {\n  id               String            @id @default(uuid())\n  iso6391          String            @unique\n  name             String\n  nativeName       String?\n  createdAt        DateTime          @default(now())\n  audioTracks      AudioTrack[]\n  contentLanguages ContentLanguage[]\n  imageAssets      ImageAsset[]\n  subtitleTracks   SubtitleTrack[]\n}\n\nmodel User {\n  id                String             @id @default(uuid())\n  email             String             @unique\n  createdAt         DateTime           @default(now())\n  deletedAt         DateTime?\n  isActive          Boolean            @default(true)\n  isCreator         Boolean            @default(false)\n  passwordHash      String?\n  role              Role               @default(USER)\n  referralCode      String?            @unique\n  updatedAt         DateTime           @updatedAt\n  createdContents   Content[]          @relation(\"ContentCreator\")\n  updatedContents   Content[]          @relation(\"ContentUpdater\")\n  creatorProfile    CreatorProfile?\n  sessions          DeviceSession[]\n  profiles          Profile[]\n  subscriptions     Subscription[]\n  payments          Payment[]\n  rentals           Rental[]\n  referralsMade     Referral[]         @relation(\"ReferrerUser\")\n  referralReceived  Referral?          @relation(\"ReferredUser\")\n  couponRedemptions CouponRedemption[]\n\n  @@index([email])\n  @@index([referralCode])\n}\n\nmodel CreatorProfile {\n  id             String                @id @default(uuid())\n  userId         String                @unique\n  currentBalance Decimal               @default(0.00) @db.Decimal(12, 2)\n  channelName    String\n  bio            String?\n  avatarUrl      String?\n  isVerified     Boolean               @default(false)\n  payoutDetails  Json?\n  createdAt      DateTime              @default(now())\n  user           User                  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  ownerships     ContentOwnership[]\n  earnings       CreatorEarning[]\n  payoutRecords  CreatorPayoutRecord[]\n}\n\n// ============================================================================\n// SUBSCRIPTION & PLAN SYSTEM\n// ============================================================================\n\nmodel SubscriptionPlan {\n  id               String          @id @default(uuid())\n  name             String          @unique\n  slug             String          @unique\n  description      String?\n  durationDays     Int             @default(30)\n  price            Decimal         @default(0.00) @db.Decimal(12, 2)\n  priceCents       Int?\n  currency         String          @default(\"KES\")\n  billingInterval  BillingInterval @default(MONTHLY)\n  maxResolution    VideoResolution @default(P1080)\n  maxProfiles      Int             @default(1)\n  maxDevices       Int             @default(1)\n  adsEnabled       Boolean         @default(true)\n  allowsDownloads  Boolean         @default(false)\n  isPremiumAccess  Boolean         @default(false)\n  isActive         Boolean         @default(true)\n  displayOrder     Int             @default(0)\n  createdAt        DateTime        @default(now())\n  updatedAt        DateTime        @updatedAt\n  subscriptions    Subscription[]\n  requiredContents Content[]       @relation(\"RequiredPlan\")\n  coupons          CouponPlan[]\n}\n\nmodel Subscription {\n  id                     String             @id @default(uuid())\n  userId                 String\n  planId                 String\n  status                 SubscriptionStatus @default(ACTIVE)\n  startDate              DateTime           @default(now())\n  currentPeriodStart     DateTime           @default(now())\n  currentPeriodEnd       DateTime?\n  endDate                DateTime           @default(now())\n  cancelledAt            DateTime?\n  trialEndsAt            DateTime?\n  autoRenew              Boolean            @default(true)\n  externalProvider       PaymentProvider?\n  externalSubscriptionId String?\n  createdAt              DateTime           @default(now())\n  updatedAt              DateTime           @updatedAt\n  plan                   SubscriptionPlan   @relation(fields: [planId], references: [id])\n  user                   User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  payments               Payment[]\n\n  @@index([userId, status])\n}\n\n// ============================================================================\n// TRANSACTIONS & PAYMENTS\n// ============================================================================\n\nmodel Payment {\n  id                    String            @id @default(uuid())\n  userId                String\n  subscriptionId        String?\n  rentalId              String?\n  amount                Decimal           @db.Decimal(12, 2)\n  currency              String            @default(\"KES\")\n  provider              PaymentProvider   @default(MPESA_DARAJA)\n  providerTransactionId String            @unique\n  providerRef           String?\n  paymentStatus         PaymentStatus     @default(PENDING)\n  paymentMethod         PaymentMethod     @default(MPESA)\n  paidAt                DateTime?\n  failedAt              DateTime?\n  refundedAt            DateTime?\n  metadata              Json?\n  createdAt             DateTime          @default(now())\n  updatedAt             DateTime          @updatedAt\n  user                  User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  subscription          Subscription?     @relation(fields: [subscriptionId], references: [id])\n  rental                Rental?\n  redemption            CouponRedemption?\n\n  @@index([userId, paymentStatus])\n  @@index([providerTransactionId])\n}\n\nmodel Rental {\n  id          String   @id @default(uuid())\n  userId      String\n  contentId   String\n  paymentId   String   @unique\n  price       Decimal  @db.Decimal(12, 2)\n  currency    String   @default(\"KES\")\n  purchasedAt DateTime @default(now())\n  expiresAt   DateTime\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  content     Content  @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  payment     Payment  @relation(fields: [paymentId], references: [id])\n\n  @@index([userId, contentId])\n  @@index([expiresAt])\n}\n\n// ============================================================================\n// ADVERTISING SYSTEM (AVOD)\n// ============================================================================\n\nmodel Advertisement {\n  id          String               @id @default(uuid())\n  advertiser  String\n  name        String\n  title       String?\n  description String?\n  mediaUrl    String\n  clickUrl    String?\n  placement   AdType               @default(PRE_ROLL)\n  isActive    Boolean              @default(true)\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n  events      AdvertisementEvent[]\n}\n\nmodel AdvertisementEvent {\n  id              String        @id @default(uuid())\n  advertisementId String\n  userId          String?\n  profileId       String?\n  contentId       String?\n  eventType       AdEventType\n  timestamp       DateTime      @default(now())\n  advertisement   Advertisement @relation(fields: [advertisementId], references: [id], onDelete: Cascade)\n\n  @@index([advertisementId, eventType])\n  @@index([timestamp])\n}\n\n// ============================================================================\n// CREATOR & REVENUE SHARE MODELS\n// ============================================================================\n\nmodel ContentOwnership {\n  id              String         @id @default(uuid())\n  creatorId       String\n  contentId       String\n  revenueSharePct Decimal        @default(60.00) @db.Decimal(5, 2)\n  creator         CreatorProfile @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n  content         Content        @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  @@unique([creatorId, contentId])\n}\n\nmodel CreatorEarning {\n  id         String         @id @default(uuid())\n  creatorId  String\n  contentId  String\n  amount     Decimal        @db.Decimal(12, 2)\n  currency   String         @default(\"KES\")\n  sourceType String\n  paymentId  String?\n  createdAt  DateTime       @default(now())\n  creator    CreatorProfile @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n  content    Content        @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  @@index([creatorId])\n  @@index([createdAt])\n}\n\nmodel CreatorPayoutRecord {\n  id            String          @id @default(uuid())\n  creatorId     String\n  amount        Decimal         @db.Decimal(12, 2)\n  currency      String          @default(\"KES\")\n  status        PayoutStatus    @default(PENDING)\n  provider      PaymentProvider @default(MPESA_DARAJA)\n  providerRef   String?\n  requestedAt   DateTime        @default(now())\n  processedAt   DateTime?\n  failureReason String?\n  createdAt     DateTime        @default(now())\n  creator       CreatorProfile  @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n\n  @@index([creatorId, status])\n}\n\nmodel EarningsEvent {\n  id             String   @id @default(uuid())\n  creatorId      String\n  contentId      String\n  amount         Decimal  @db.Decimal(10, 2)\n  sourceType     String\n  watchHistoryId String?  @unique\n  createdAt      DateTime @default(now())\n\n  @@index([creatorId])\n  @@index([createdAt])\n}\n\nmodel CreatorPayout {\n  id          String    @id @default(uuid())\n  creatorId   String\n  amount      Decimal   @db.Decimal(10, 2)\n  status      String    @default(\"PENDING\")\n  description String?\n  paidAt      DateTime?\n  createdAt   DateTime  @default(now())\n}\n\n// ============================================================================\n// REFERRALS & COUPONS\n// ============================================================================\n\nmodel Referral {\n  id             String    @id @default(uuid())\n  referrerId     String\n  referredUserId String    @unique\n  code           String\n  status         String    @default(\"PENDING\")\n  rewardGiven    Boolean   @default(false)\n  createdAt      DateTime  @default(now())\n  convertedAt    DateTime?\n  referrer       User      @relation(\"ReferrerUser\", fields: [referrerId], references: [id])\n  referredUser   User      @relation(\"ReferredUser\", fields: [referredUserId], references: [id])\n\n  @@index([code])\n}\n\nmodel Coupon {\n  id              String             @id @default(uuid())\n  code            String             @unique\n  discountType    CouponDiscountType @default(PERCENTAGE)\n  discountValue   Decimal            @db.Decimal(12, 2)\n  currency        String             @default(\"KES\")\n  maxRedemptions  Int                @default(100)\n  redemptionCount Int                @default(0)\n  startDate       DateTime?\n  expiresAt       DateTime?\n  minPurchaseAmt  Decimal?           @db.Decimal(12, 2)\n  isActive        Boolean            @default(true)\n  createdAt       DateTime           @default(now())\n  updatedAt       DateTime           @updatedAt\n  plans           CouponPlan[]\n  redemptions     CouponRedemption[]\n}\n\nmodel CouponPlan {\n  couponId String\n  planId   String\n  coupon   Coupon           @relation(fields: [couponId], references: [id], onDelete: Cascade)\n  plan     SubscriptionPlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@id([couponId, planId])\n}\n\nmodel CouponRedemption {\n  id         String   @id @default(uuid())\n  couponId   String\n  userId     String\n  paymentId  String   @unique\n  redeemedAt DateTime @default(now())\n  coupon     Coupon   @relation(fields: [couponId], references: [id])\n  user       User     @relation(fields: [userId], references: [id])\n  payment    Payment  @relation(fields: [paymentId], references: [id])\n}\n\nmodel FinancialLedger {\n  id              String   @id @default(uuid())\n  paymentId       String?  @unique\n  grossRevenue    Decimal  @db.Decimal(12, 2)\n  gatewayFee      Decimal  @default(0.00) @db.Decimal(12, 2)\n  creatorRevShare Decimal  @default(0.00) @db.Decimal(12, 2)\n  netPlatformRev  Decimal  @db.Decimal(12, 2)\n  currency        String   @default(\"KES\")\n  recordedAt      DateTime @default(now())\n}\n\n// ============================================================================\n// PROFILES, DEVICE SESSIONS & WATCH INFRASTRUCTURE\n// ============================================================================\n\nmodel DeviceSession {\n  id           String     @id @default(uuid())\n  userId       String\n  deviceUuid   String\n  deviceName   String\n  deviceType   DeviceType @default(WEB)\n  ipAddress    String?\n  refreshToken String     @unique\n  lastActiveAt DateTime   @updatedAt\n  createdAt    DateTime   @default(now())\n  user         User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, deviceUuid])\n  @@index([userId])\n  @@index([deviceUuid])\n}\n\nmodel Profile {\n  id              String                @id @default(uuid())\n  userId          String\n  name            String\n  avatarUrl       String?\n  createdAt       DateTime              @default(now())\n  deletedAt       DateTime?\n  maxMaturityId   String\n  pinLockCode     String?\n  updatedAt       DateTime              @updatedAt\n  downloads       Download[]\n  myList          MyListItem[]\n  maxMaturity     MaturityRating        @relation(fields: [maxMaturityId], references: [id])\n  user            User                  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  settings        ProfileSettings?\n  ratings         Rating[]\n  recommendations RecommendationScore[]\n  watchHistory    WatchHistory[]\n\n  @@index([userId])\n}\n\nmodel ProfileSettings {\n  id                String   @id @default(uuid())\n  profileId         String   @unique\n  interfaceLanguage String   @default(\"en\")\n  audioLanguage     String   @default(\"en\")\n  subtitleLanguage  String   @default(\"en\")\n  autoplayNext      Boolean  @default(true)\n  autoplayPreviews  Boolean  @default(true)\n  updatedAt         DateTime @updatedAt\n  profile           Profile  @relation(fields: [profileId], references: [id], onDelete: Cascade)\n}\n\nmodel Content {\n  id                  String                     @id @default(uuid())\n  title               String\n  slug                String                     @unique\n  description         String?\n  storyline           String?\n  releaseYear         Int?\n  status              ContentStatus              @default(DRAFT)\n  accessType          ContentAccessType          @default(FREE)\n  requiredPlanId      String?\n  rentalPrice         Decimal?                   @db.Decimal(12, 2)\n  rentalDurationHours Int?                       @default(48)\n  purchasePrice       Decimal?                   @db.Decimal(12, 2)\n  currency            String                     @default(\"KES\")\n  isMonetized         Boolean                    @default(true)\n  maturityRatingId    String\n  imdbId              String?                    @unique\n  tmdbId              Int?                       @unique\n  tvdbId              String?                    @unique\n  traktId             Int?                       @unique\n  popularityScore     Float                      @default(0.0)\n  viewCount           BigInt                     @default(0)\n  watchSeconds        BigInt                     @default(0)\n  playCount           Int                        @default(0)\n  createdById         String\n  updatedById         String\n  publishedAt         DateTime?\n  createdAt           DateTime                   @default(now())\n  updatedAt           DateTime                   @updatedAt\n  featuredOrder       Int                        @default(0)\n  isFeatured          Boolean                    @default(false)\n  awards              Award[]\n  cast                Cast[]\n  collections         CollectionItem[]\n  createdBy           User                       @relation(\"ContentCreator\", fields: [createdById], references: [id])\n  maturityRating      MaturityRating             @relation(fields: [maturityRatingId], references: [id])\n  updatedBy           User                       @relation(\"ContentUpdater\", fields: [updatedById], references: [id])\n  requiredPlan        SubscriptionPlan?          @relation(\"RequiredPlan\", fields: [requiredPlanId], references: [id])\n  categories          ContentCategory[]\n  countries           ContentCountry[]\n  languages           ContentLanguage[]\n  productionCos       ContentProductionCompany[]\n  studios             ContentStudio[]\n  crew                Crew[]\n  images              ImageAsset[]\n  movies              Movie[]\n  myListItems         MyListItem[]\n  ratings             Rating[]\n  sourcedRecomms      RecommendationScore[]      @relation(\"SourceContent\")\n  targetedRecomms     RecommendationScore[]      @relation(\"TargetContent\")\n  show                Show?\n  trailers            Trailer[]\n  rentals             Rental[]\n  ownerships          ContentOwnership[]\n  creatorEarnings     CreatorEarning[]\n\n  @@index([title])\n  @@index([status])\n  @@index([accessType])\n  @@index([createdById])\n  @@index([isFeatured])\n}\n\nmodel Movie {\n  id            String  @id @default(uuid())\n  contentId     String\n  cutVariant    String  @default(\"Theatrical\")\n  durationTotal Int\n  videoId       String  @unique\n  content       Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  video         Video   @relation(fields: [videoId], references: [id])\n\n  @@index([contentId])\n}\n\nmodel Show {\n  id        String   @id @default(uuid())\n  contentId String   @unique\n  seasons   Season[]\n  content   Content  @relation(fields: [contentId], references: [id], onDelete: Cascade)\n}\n\nmodel Season {\n  id           String       @id @default(uuid())\n  seasonNumber Int\n  title        String?\n  slug         String       @unique\n  description  String?\n  showId       String\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n  episodes     Episode[]\n  images       ImageAsset[]\n  show         Show         @relation(fields: [showId], references: [id], onDelete: Cascade)\n\n  @@unique([showId, seasonNumber])\n  @@index([showId])\n}\n\nmodel Episode {\n  id              String    @id @default(uuid())\n  episodeNumber   Int\n  title           String\n  slug            String    @unique\n  description     String?\n  releaseDate     DateTime?\n  seasonId        String\n  nextEpisodeId   String?   @unique\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  videoId         String    @unique\n  nextEpisode     Episode?  @relation(\"EpisodeChaining\", fields: [nextEpisodeId], references: [id])\n  previousEpisode Episode?  @relation(\"EpisodeChaining\")\n  season          Season    @relation(fields: [seasonId], references: [id], onDelete: Cascade)\n  video           Video     @relation(fields: [videoId], references: [id])\n\n  @@unique([seasonId, episodeNumber])\n  @@index([seasonId])\n}\n\nmodel Person {\n  id        String    @id @default(uuid())\n  name      String\n  slug      String    @unique\n  biography String?\n  avatarUrl String?\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  castRoles Cast[]\n  crewRoles Crew[]\n\n  @@index([name])\n}\n\nmodel Studio {\n  id        String          @id @default(uuid())\n  name      String          @unique\n  slug      String          @unique\n  createdAt DateTime        @default(now())\n  contents  ContentStudio[]\n}\n\nmodel ProductionCompany {\n  id        String                     @id @default(uuid())\n  name      String                     @unique\n  slug      String                     @unique\n  createdAt DateTime                   @default(now())\n  contents  ContentProductionCompany[]\n}\n\nmodel Country {\n  id        String           @id @default(uuid())\n  isoAlpha2 String           @unique\n  name      String           @unique\n  contents  ContentCountry[]\n}\n\nmodel Cast {\n  id           String  @id @default(uuid())\n  character    String\n  displayOrder Int     @default(0)\n  personId     String\n  contentId    String\n  content      Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  person       Person  @relation(fields: [personId], references: [id], onDelete: Cascade)\n\n  @@index([personId])\n  @@index([contentId])\n  @@index([displayOrder])\n}\n\nmodel Crew {\n  id         String  @id @default(uuid())\n  job        String\n  department String\n  personId   String\n  contentId  String\n  content    Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  person     Person  @relation(fields: [personId], references: [id], onDelete: Cascade)\n\n  @@index([personId])\n  @@index([contentId])\n}\n\nmodel Category {\n  id        String            @id @default(uuid())\n  name      String            @unique\n  slug      String            @unique\n  createdAt DateTime          @default(now())\n  contents  ContentCategory[]\n}\n\nmodel Collection {\n  id          String           @id @default(uuid())\n  name        String\n  slug        String           @unique\n  description String?\n  isActive    Boolean          @default(true)\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n  items       CollectionItem[]\n  homeRows    HomepageRow[]\n}\n\nmodel HomepageRow {\n  id           String         @id @default(uuid())\n  title        String\n  displayOrder Int            @unique\n  renderStyle  RowRenderStyle @default(STANDARD_POSTER)\n  sourceType   RowDataSource  @default(CURATED_COLLECTION)\n  isActive     Boolean        @default(true)\n  collectionId String?\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n  categoryId   String?\n  collection   Collection?    @relation(fields: [collectionId], references: [id])\n\n  @@index([displayOrder])\n  @@index([sourceType])\n}\n\nmodel ContentCategory {\n  contentId  String\n  categoryId String\n  isPrimary  Boolean  @default(false)\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  content    Content  @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  @@id([contentId, categoryId])\n  @@index([contentId])\n  @@index([categoryId])\n}\n\nmodel CollectionItem {\n  collectionId String\n  contentId    String\n  displayOrder Int        @default(0)\n  isFeatured   Boolean    @default(false)\n  collection   Collection @relation(fields: [collectionId], references: [id], onDelete: Cascade)\n  content      Content    @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  @@id([collectionId, contentId])\n  @@index([collectionId])\n  @@index([contentId])\n  @@index([displayOrder])\n}\n\nmodel ContentLanguage {\n  contentId  String\n  languageId String\n  isDubbed   Boolean          @default(false)\n  isSubbed   Boolean          @default(true)\n  content    Content          @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  language   LanguageRegistry @relation(fields: [languageId], references: [id], onDelete: Cascade)\n\n  @@id([contentId, languageId])\n}\n\nmodel ContentStudio {\n  contentId String\n  studioId  String\n  content   Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  studio    Studio  @relation(fields: [studioId], references: [id], onDelete: Cascade)\n\n  @@id([contentId, studioId])\n}\n\nmodel ContentProductionCompany {\n  contentId           String\n  productionCompanyId String\n  content             Content           @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  productionCompany   ProductionCompany @relation(fields: [productionCompanyId], references: [id], onDelete: Cascade)\n\n  @@id([contentId, productionCompanyId])\n}\n\nmodel ContentCountry {\n  contentId String\n  countryId String\n  content   Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  country   Country @relation(fields: [countryId], references: [id], onDelete: Cascade)\n\n  @@id([contentId, countryId])\n}\n\nmodel Award {\n  id        String   @id @default(uuid())\n  contentId String\n  academy   String\n  year      Int\n  category  String\n  isWinner  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  content   Content  @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  @@index([contentId])\n}\n\nmodel ImageAsset {\n  id           String           @id @default(uuid())\n  url          String\n  type         AssetType        @default(POSTER)\n  width        Int?\n  height       Int?\n  displayOrder Int              @default(0)\n  languageId   String\n  contentId    String?\n  seasonId     String?\n  createdAt    DateTime         @default(now())\n  content      Content?         @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  language     LanguageRegistry @relation(fields: [languageId], references: [id])\n  season       Season?          @relation(fields: [seasonId], references: [id], onDelete: Cascade)\n\n  @@index([contentId])\n  @@index([seasonId])\n}\n\nmodel Trailer {\n  id              String   @id @default(uuid())\n  title           String\n  hlsManifestUrl  String\n  durationSeconds Int?\n  contentId       String\n  createdAt       DateTime @default(now())\n  content         Content  @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  @@index([contentId])\n}\n\nmodel Video {\n  id              String          @id @default(uuid())\n  durationSeconds Int\n  createdAt       DateTime        @default(now())\n  introEnd        Int?            @default(0)\n  introStart      Int?            @default(0)\n  creditsEnd      Int?\n  creditsStart    Int?\n  recapEnd        Int?            @default(0)\n  recapStart      Int?            @default(0)\n  updatedAt       DateTime        @updatedAt\n  audioTracks     AudioTrack[]\n  downloads       Download[]\n  episode         Episode?\n  movie           Movie?\n  subtitles       SubtitleTrack[]\n  sources         VideoSource[]\n  watchHistory    WatchHistory[]\n}\n\nmodel VideoSource {\n  id                     String               @id @default(uuid())\n  type                   VideoSourceType      @default(HLS)\n  url                    String\n  resolution             VideoResolution      @default(P1080)\n  bitrate                Int?\n  codec                  String\n  audioCodec             String\n  fps                    Float\n  hdr                    HDRFormat            @default(SDR)\n  aspectRatio            String\n  videoId                String\n  widevineKeyId          String?\n  widevineLicenseUrl     String?\n  fairplayAssetId        String?\n  fairplayCertificateUrl String?\n  playreadyHeader        String?\n  regions                RegionAvailability[]\n  video                  Video                @relation(fields: [videoId], references: [id], onDelete: Cascade)\n\n  @@index([videoId])\n}\n\nmodel SubtitleTrack {\n  id         String           @id @default(uuid())\n  languageId String\n  label      String\n  url        String\n  isCC       Boolean          @default(false)\n  videoId    String\n  language   LanguageRegistry @relation(fields: [languageId], references: [id])\n  video      Video            @relation(fields: [videoId], references: [id], onDelete: Cascade)\n\n  @@index([videoId])\n}\n\nmodel AudioTrack {\n  id            String           @id @default(uuid())\n  languageId    String\n  label         String\n  url           String?\n  isDescriptive Boolean          @default(false)\n  videoId       String\n  language      LanguageRegistry @relation(fields: [languageId], references: [id])\n  video         Video            @relation(fields: [videoId], references: [id], onDelete: Cascade)\n\n  @@index([videoId])\n}\n\nmodel RegionAvailability {\n  id            String      @id @default(uuid())\n  countryCode   String\n  isAllowed     Boolean     @default(true)\n  expiresAt     DateTime?\n  videoSourceId String\n  videoSource   VideoSource @relation(fields: [videoSourceId], references: [id], onDelete: Cascade)\n\n  @@unique([countryCode, videoSourceId])\n  @@index([videoSourceId])\n}\n\nmodel WatchHistory {\n  id          String    @id @default(uuid())\n  profileId   String\n  videoId     String\n  lastTime    Int       @default(0)\n  isFinished  Boolean   @default(false)\n  updatedAt   DateTime  @updatedAt\n  completedAt DateTime?\n  createdAt   DateTime  @default(now())\n  profile     Profile   @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  video       Video     @relation(fields: [videoId], references: [id], onDelete: Cascade)\n\n  @@unique([profileId, videoId])\n  @@index([profileId])\n  @@index([videoId])\n  @@index([updatedAt])\n}\n\nmodel MyListItem {\n  id           String   @id @default(uuid())\n  profileId    String\n  contentId    String\n  displayOrder Int      @default(0)\n  createdAt    DateTime @default(now())\n  content      Content  @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  profile      Profile  @relation(fields: [profileId], references: [id], onDelete: Cascade)\n\n  @@unique([profileId, contentId])\n  @@index([profileId])\n  @@index([displayOrder])\n}\n\nmodel Rating {\n  id        String      @id @default(uuid())\n  value     RatingValue\n  profileId String\n  contentId String\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n  content   Content     @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  profile   Profile     @relation(fields: [profileId], references: [id], onDelete: Cascade)\n\n  @@unique([profileId, contentId])\n  @@index([profileId])\n  @@index([contentId])\n}\n\nmodel RecommendationScore {\n  id              String   @id @default(uuid())\n  profileId       String\n  targetContentId String\n  predictedScore  Float\n  reasonCode      String?\n  sourceContentId String?\n  updatedAt       DateTime @updatedAt\n  profile         Profile  @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  sourceContent   Content? @relation(\"SourceContent\", fields: [sourceContentId], references: [id])\n  targetContent   Content  @relation(\"TargetContent\", fields: [targetContentId], references: [id], onDelete: Cascade)\n\n  @@unique([profileId, targetContentId])\n  @@index([profileId, predictedScore])\n}\n\nmodel Download {\n  id         String   @id @default(uuid())\n  profileId  String\n  videoId    String\n  deviceUuid String\n  authToken  String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  profile    Profile  @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  video      Video    @relation(fields: [videoId], references: [id], onDelete: Cascade)\n\n  @@unique([profileId, videoId, deviceUuid])\n  @@index([profileId])\n}\n"
}

